style.css:
@-moz-document domain("youtube.com"), url-prefix("https://www.youtube.com") {
/* General Background */
  body, #content, ytd-app {
    background-color: #181818 !important;
    color: #e3e3e3 !important;
  }

  /* Header */
  #masthead-container {
    background: linear-gradient(90deg, #1a1a1a, #2a2a2a) !important;
    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.5) !important;
  }

  /* Search Bar */
  #search-form input {
    background-color: #252525 !important;
    color: #e3e3e3 !important;
    border: 1px solid #444 !important;
  }
  #search-icon-legacy {
    background-color: #444 !important;
    color: #e3e3e3 !important;
  }

  /* Video Thumbnails */
  ytd-thumbnail {
    border-radius: 10px !important;
    overflow: hidden !important;
  }

  /* Sidebar */
  ytd-mini-guide-renderer, ytd-guide-section-renderer {
    background-color: #202020 !important;
    border-color: #303030 !important;
  }
  ytd-mini-guide-entry-renderer, ytd-guide-entry-renderer {
    color: #b3b3b3 !important;
  }

  /* Video Titles */
  h3.title, h1.title {
    color: #ffffff !important;
  }

  /* Video Player */
  .html5-video-container video {
    border-radius: 10px !important;
  }

  /* Buttons and Links */
  a, yt-icon {
    color: #1e90ff !important;
  }
  a:hover {
    color: #00bfff !important;
  }

  /* Footer */
  ytd-footer-renderer {
    background-color: #181818 !important;
    color: #666 !important;
  }

  /* Hover Effects */
  ytd-thumbnail:hover {
    transform: scale(1.02) !important;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.3) !important;
  }
}
